def alphabet_languages(characters: list[str], ignore_non_latin: bool=False) -> list[str]:
    """
    Return associated languages associated to given characters.
    """
    if not characters:
        return []

    languages = set()

    # First, collect all unique Unicode ranges present in all characters
    character_ranges = set()
    for char in characters:
        char_range = unicode_range(char)
        if char_range is not None:
            character_ranges.add(char_range)

    # If we have non-Latin ranges, check those first
    non_latin_ranges = [r for r in character_ranges if 'Latin' not in r]
    if non_latin_ranges:
        for char_range in non_latin_ranges:
            languages.update(unicode_range_languages(char_range))

    # If we still don't have languages, or if we only have Latin ranges,
    # check all languages based on character matches
    if not languages or all('Latin' in r for r in character_ranges):
        for language, language_characters in FREQUENCIES.items():
